const hex = n => { let s = ''; for (let i = 0; i < n; i++) { s += Math.floor(Math.random() * 16).toString(16); } return s; };
const hexRe32 = /^[0-9a-f]{32}$/i;
const hexRe16 = /^[0-9a-f]{16}$/i;
return $input.all().map(item => {
  const j = item.json;
  const traceId = hexRe32.test(String(j.trace_id || '')) ? String(j.trace_id).toLowerCase() : hex(32);
  const parentId = hexRe16.test(String(j.parent_span_id || '')) ? String(j.parent_span_id).toLowerCase() : '';
  return { json: Object.assign({}, j, { trace_id: traceId, parent_span_id: parentId, span_id: hex(16), test_case_id: j.test_case_id || '', start_time_ns: String(Date.now()) + '000000' }) };
});

/**
 * MIRA — Parse Status Output v2.9
 * n8n Code Node: Run Once for All Items
 *
 * Request-specific task selection
 * Source-grounded task and blocker reconciliation
 * Sprint isolation and risk diagnostics
 * Legacy output compatibility
 */

const trig =
  $('When Orchestrator Requests Status').first().json || {};

const item = $input.first()?.json || {};

const str = x => String(x ?? '').trim();
const arr = x => Array.isArray(x) ? x : [];
const obj = x =>
  x && typeof x === 'object' && !Array.isArray(x)
    ? x
    : {};

const unique = values => [...new Set(values)];

const base = {
  agent: 'status',
  snapshot_id: str(trig.snapshot_id),
  generated_at: new Date().toISOString(),
  trace_id: str(trig.trace_id)
};

const emptyCounts = {
  total: 0,
  completed: 0,
  in_progress: 0,
  not_started: 0,
  blocked: 0
};

function failure(message) {
  return [{
    json: {
      ...base,
      status: 'error',
      error_detail: message,
      tasks: [],
      task_counts: { ...emptyCounts },
      data_gaps: [message],
      task_counts_validated: false,
      task_counts_reconciled: false,
      validation_status: 'FAILED'
    }
  }];
}

// ==================================================
// 1. HANDLE AGENT ERRORS
// ==================================================

if (item.error) {
  return failure(str(item.error.message || item.error));
}

// ==================================================
// 2. PARSE STRUCTURED AGENT OUTPUT
// ==================================================

let parsed = item.output ?? item.text ?? item;

if (typeof parsed === 'string') {
  const clean = parsed.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '');

  try {
    parsed = JSON.parse(clean);
  } catch {
    return failure('AI Agent returned invalid JSON.');
  }
}

if (
  parsed?.output &&
  typeof parsed.output === 'object' &&
  !Array.isArray(parsed.output)
) {
  parsed = parsed.output;
}

if (
  !parsed ||
  typeof parsed !== 'object' ||
  Array.isArray(parsed)
) {
  return failure(
    'AI Agent returned no structured status report.'
  );
}

// ==================================================
// 3. RETRIEVE SOURCE TASKS
// ==================================================

function normalizeTask(t) {
  const x = obj(t);

  return {
    task_id: str(x.task_id),
    task_name: str(x.task_name ?? x.name),
    status: str(x.status),
    assignee: str(x.assignee ?? x.owner),
    sprint: str(x.sprint),
    due_date: str(x.due_date),
    description: str(
      x.description ??
      x.blocker_reason ??
      x.notes
    )
  };
}

function getSourceTasks(context) {
  let data = context;

  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch {
      // Keep formatted text representation.
    }
  }

  if (data && typeof data === 'object') {
    const root = obj(data);

    const file = arr(root.files).find(f =>
      str(f.file_name ?? f.name).toLowerCase() ===
      'sample_task_board.csv'
    );

    if (file) {
      let content = file.content;

      if (typeof content === 'string') {
        try {
          content = JSON.parse(content);
        } catch {
          // Try formatted text below.
        }
      }

      if (Array.isArray(content)) {
        return content.map(normalizeTask);
      }

      if (Array.isArray(content?.rows)) {
        return content.rows.map(normalizeTask);
      }
    }
  }

  const textContext =
    typeof context === 'string' ? context : '';

  const match = textContext.match(
    /### FILE:\s*sample_task_board\.csv\s*\(task_board\)\s*\n([\s\S]*?)(?=\n### FILE:|$)/i
  );

  if (!match) return [];

  return match[1]
    .split(/\r?\n/)
    .filter(line => /^T\d+\s*\|/.test(line.trim()))
    .map(line => {
      const c = line.split('|').map(x => x.trim());

      return normalizeTask({
        task_id: c[0],
        task_name: c[1],
        status: c[2],
        assignee: c[3],
        sprint: c[5],
        due_date: c[6],
        description: c.slice(7).join(' | ')
      });
    });
}

const allTasks = getSourceTasks(trig.project_context);

if (!base.snapshot_id || !allTasks.length) {
  return failure(
    'Sample task-board records are unavailable in the supplied project context.'
  );
}

// ==================================================
// 4. DETERMINE REQUEST-SPECIFIC SCOPE
// ==================================================

const request = str(trig.request_text);

const requestedSprint =
  request.match(/\bSprint\s+(\d+)\b/i);

const sprint = requestedSprint
  ? `Sprint ${requestedSprint[1]}`
  : '';

// A missing sprint does not automatically mean
// the user requested the entire project.

const asksBlocked =
  /\b(blocked|blockers?)\b/i.test(request);

const asksDeadlineRisk =
  /\b(at[ -]?risk|deadline|due dates?|overdue|late|delay|behind schedule|missing (?:a |the )?deadline)\b/i
    .test(request);


const asksStatusBreakdown =
  /\b(done|completed|in progress|to do|not started)\b/i
    .test(request) &&
  /\b(status|progress|summari[sz]e|breakdown|counts?|tasks?)\b/i
    .test(request);

const isBlockedOnly =
  asksBlocked &&
  !asksDeadlineRisk &&
  !asksStatusBreakdown;

const isDeadlineFocused = asksDeadlineRisk;
const isFocused = isBlockedOnly || isDeadlineFocused;
const isProjectWide = !sprint && !isFocused;

// Date comparisons flag snapshot-review concerns, NOT
// confirmed live overdue status. Use UTC date of execution.
const comparisonDate = new Date().toISOString().slice(0, 10);

const hasPastRecordedDeadline = t =>
  /^\d{4}-\d{2}-\d{2}$/.test(t.due_date) &&
  t.due_date < comparisonDate;

const needsDeadlineReview = t =>
  t.status !== 'Done' && hasPastRecordedDeadline(t);

// Focused selection, independent of the model's task list.
const selected = allTasks.filter(t => {
  if (
    sprint &&
    t.sprint.toLowerCase() !== sprint.toLowerCase()
  ) {
    return false;
  }

  if (isBlockedOnly) {
    return t.status === 'Blocked';
  }

  if (isDeadlineFocused) {
    return (
      (asksBlocked && t.status === 'Blocked') ||
      needsDeadlineReview(t)
    );
  }

  return true;
});

if (!selected.length && !isFocused) {
  return failure(
    sprint
      ? `No source tasks match ${sprint}.`
      : 'No task records are available.'
  );
}

// ==================================================
// 4A. DETECT MODEL SCOPE MISMATCH
// ==================================================

const modelSprint = str(parsed.sprint);

const normalizedModelSprint =
  modelSprint.toLowerCase();

const projectWideAliases = new Set([
  '',
  'all',
  'all sprints',
  'all project sprints',
  'project',
  'project-wide',
  'project wide',
  'full project'
]);

const modelSprintMismatch = Boolean(
  sprint
    ? normalizedModelSprint !== '' &&
      normalizedModelSprint !== sprint.toLowerCase()
    : !projectWideAliases.has(normalizedModelSprint)
);

const modelTaskIds = arr(parsed.tasks)
  .map(t => str(obj(t).task_id).toUpperCase())
  .filter(Boolean);

const selectedTaskIds = selected.map(
  t => t.task_id.toUpperCase()
);

const modelTaskScopeMismatch =
  modelTaskIds.length > 0 && (
    modelTaskIds.length !== selectedTaskIds.length ||
    modelTaskIds.some(id => !selectedTaskIds.includes(id))
  );

const modelRiskScopeMismatch =
  isFocused && arr(parsed.risks).length > 0;

const modelScopeMismatch =
  modelSprintMismatch ||
  modelTaskScopeMismatch ||
  modelRiskScopeMismatch;

// ==================================================
// 5. VALIDATE SOURCE TASKS
// ==================================================

const allowedStatuses = [
  'Done',
  'In Progress',
  'To Do',
  'Blocked'
];

const taskIds = selected.map(t => t.task_id);

const hasDuplicateIds =
  new Set(taskIds).size !== taskIds.length;

if (hasDuplicateIds) {
  return failure(
    'Duplicate task IDs found in source records.'
  );
}

const invalidTasks = selected.filter(t =>
  !t.task_id ||
  !t.task_name ||
  !allowedStatuses.includes(t.status)
);

if (invalidTasks.length) {
  return failure(
    'Source task records contain missing identities or unsupported statuses.'
  );
}

// ==================================================
// 6. CANONICAL TASKS AND COUNTS
// ==================================================

const tasks = selected.map(t => ({
  task_id: t.task_id,
  name: t.task_name,
  status: t.status,
  owner: t.assignee || null,
  sprint: t.sprint || null,
  due_date: t.due_date || null,
  evidence: `sample_task_board.csv#${t.task_id}`
}));

const count = status =>
  tasks.filter(t => t.status === status).length;

const task_counts = {
  total: tasks.length,
  completed: count('Done'),
  in_progress: count('In Progress'),
  not_started: count('To Do'),
  blocked: count('Blocked')
};

const status_counts = {
  Done: task_counts.completed,
  'In Progress': task_counts.in_progress,
  'To Do': task_counts.not_started,
  Blocked: task_counts.blocked
};

const countsMatch =
  task_counts.total ===
  task_counts.completed +
  task_counts.in_progress +
  task_counts.not_started +
  task_counts.blocked;

// ==================================================
// 7. CANONICAL BLOCKERS
// ==================================================

const blockedSourceTasks = selected.filter(
  t => t.status === 'Blocked'
);

const blockers = blockedSourceTasks.map(t => {
  const parts = [
    `${t.task_id} — ${t.task_name}`,
    'Status: Blocked'
  ];

  if (t.assignee) {
    parts.push(`Assignee: ${t.assignee}`);
  }

  if (t.due_date) {
    parts.push(
      `Recorded due date: ${t.due_date}`
    );
  }

  if (t.description) {
    parts.push(
      `Recorded details: ${t.description}`
    );
  }

  parts.push(
    `Source: sample_task_board.csv#${t.task_id}`
  );

  return parts.join('; ');
});

const blockerIds = blockedSourceTasks.map(
  t => t.task_id
);

const blockersMatch =
  blockers.length === task_counts.blocked &&
  new Set(blockerIds).size === blockerIds.length;

// ==================================================
// 8. GROUNDED TASK SUMMARY
// ==================================================

const scopeLabel = isBlockedOnly
  ? (sprint ? `${sprint} blocked` : 'Blocked')
  : isDeadlineFocused
    ? (
        sprint
          ? `${sprint} deadline concerns`
          : 'Blockers and deadline concerns'
      )
    : (sprint || 'Project-wide');

const deadlineConcernTasks =
  selected.filter(needsDeadlineReview);

const additionalDeadlineConcerns =
  deadlineConcernTasks.filter(
    t => t.status !== 'Blocked'
  );

const canonicalSummary =
  `${scopeLabel} task summary: ` +
  `${task_counts.total} selected, ` +
  `${task_counts.completed} Done, ` +
  `${task_counts.in_progress} In Progress, ` +
  `${task_counts.not_started} To Do, ` +
  `${task_counts.blocked} Blocked.` +
  (
    isDeadlineFocused
      ? ` ${additionalDeadlineConcerns.length} additional unfinished tasks have recorded due dates before ${comparisonDate}; these are historical schedule-review concerns, not verified live delays.`
      : ''
  );

const summary = canonicalSummary;

// ==================================================
// 9. VALIDATE MODEL TASK REFERENCES
// ==================================================

const selectedIds = new Set(
  selected.map(t => t.task_id.toUpperCase())
);

const taskIdPattern = /\bT\d{3,}\b/gi;

function referencesOnlySelectedTasks(value) {
  const ids =
    str(value).match(taskIdPattern) || [];

  return ids.every(id =>
    selectedIds.has(id.toUpperCase())
  );
}

function scopedStrings(values) {
  return arr(values)
    .filter(x => typeof x === 'string')
    .map(str)
    .filter(Boolean)
    .filter(referencesOnlySelectedTasks);
}

const highlights = scopedStrings(parsed.highlights)
  .filter(h =>
    !isFocused ||
    selected.some(t => h.includes(t.task_id))
  );

if (isDeadlineFocused) {
  highlights.push(
    `${task_counts.blocked} documented blocked task(s); ` +
    `${additionalDeadlineConcerns.length} other unfinished task(s) ` +
    `with recorded due dates before ${comparisonDate}. ` +
    'Current live deadline compliance has not been verified.'
  );
}

// ==================================================
// 10. RISK REGISTER EXTRACTION
// ==================================================

function parseDelimitedLine(line, delimiter) {
  const values = [];
  let field = '';
  let quoted = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (ch === '"') {
      if (quoted && line[i + 1] === '"') {
        field += '"';
        i++;
      } else {
        quoted = !quoted;
      }
    } else if (ch === delimiter && !quoted) {
      values.push(field.trim());
      field = '';
    } else {
      field += ch;
    }
  }

  values.push(field.trim());
  return values;
}

function getRiskRecords(context) {
  let data = context;

  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch {
      // Formatted source text.
    }
  }

  let content;

  if (data && typeof data === 'object') {
    const root = obj(data);

    const file = arr(root.files).find(f =>
      str(f.file_name ?? f.name).toLowerCase() ===
      'project_risks.csv'
    );

    if (file) {
      content =
        file.content ??
        file.rows ??
        file.records;
    }
  }

  if (
    content == null &&
    typeof context === 'string'
  ) {
    const section = context.match(
      /### FILE:\s*project_risks\.csv(?:\s*\([^\n)]*\))?\s*\n([\s\S]*?)(?=\n### FILE:|$)/i
    );

    if (section) {
      content = section[1];
    }
  }

  if (typeof content === 'string') {
    try {
      content = JSON.parse(content);
    } catch {
      // CSV or pipe-delimited source.
    }
  }

  if (
    content &&
    typeof content === 'object' &&
    !Array.isArray(content)
  ) {
    content =
      content.rows ??
      content.records ??
      content.risks ??
      content;
  }

  let rows = [];

  if (Array.isArray(content)) {
    rows = content;
  } else if (typeof content === 'string') {
    const lines = content
      .split(/\r?\n/)
      .map(x => x.trim())
      .filter(Boolean)
      .filter(
        x => !/^\|?\s*[-:| ]+\s*\|?$/.test(x)
      );

    if (!lines.length) return [];

    const pipe = lines.some(line =>
      /^\|?\s*R\d+\s*\|/i.test(line)
    );

    const delimiter = pipe ? '|' : ',';

    const cells = lines.map(line => {
      const normalized = pipe
        ? line
            .replace(/^\|\s*/, '')
            .replace(/\s*\|$/, '')
        : line;

      return parseDelimitedLine(
        normalized,
        delimiter
      );
    });

    const headers = cells[0].map(h =>
      h.toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_|_$/g, '')
    );

    const hasHeader = headers.some(h =>
      ['risk_id', 'riskid', 'id'].includes(h)
    );

    rows = (
      hasHeader ? cells.slice(1) : cells
    ).map(c => {
      const record = {};

      for (let i = 0; i < c.length; i++) {
        record[
          hasHeader
            ? (headers[i] || `field_${i + 1}`)
            : `field_${i + 1}`
        ] = c[i];
      }

      if (!hasHeader) {
        record.risk_id = c.find(v =>
          /^R\d+$/i.test(str(v))
        );
      }

      return record;
    });
  }

  const result = [];
  const seen = new Set();

  for (const record of rows) {
    const r = obj(record);

    const id = str(
      r.risk_id ??
      r.riskid ??
      r.id
    ).toUpperCase();

    if (!/^R\d+$/.test(id) || seen.has(id)) {
      continue;
    }

    seen.add(id);

    const details = Object.entries(r)
      .filter(([key, value]) =>
        !['risk_id', 'riskid', 'id'].includes(key) &&
        value !== null &&
        value !== undefined &&
        str(value)
      )
      .map(([key, value]) =>
        `${key}: ${str(value)}`
      );

    result.push(
      `${id}; ${details.join('; ')}; ` +
      `Source: project_risks.csv#${id}`
    );
  }

  return result;
}

// ==================================================
// 10A. RISK SOURCE DIAGNOSTICS
// ==================================================

const rawContext = trig.project_context;

let structuredContext = rawContext;

if (typeof structuredContext === 'string') {
  try {
    structuredContext = JSON.parse(
      structuredContext
    );
  } catch {
    // Preserve text representation.
  }
}

const contextFiles =
  arr(obj(structuredContext).files);

const contextFileNames = contextFiles.map(f =>
  str(f.file_name ?? f.name)
);

const contextText =
  typeof rawContext === 'string'
    ? rawContext
    : JSON.stringify(rawContext ?? {});

const contextHasRiskFilename =
  /project_risks\.csv/i.test(contextText);

const contextHasRiskIds =
  /\bR\d{1,3}\b/i.test(contextText);

const contextRiskFiles =
  contextFileNames.filter(name =>
    /risk/i.test(name)
  );

const canonicalRisks = getRiskRecords(
  trig.project_context
);

// Only include project risk records for the
// applicable report scope.

const risks = isProjectWide
  ? unique(canonicalRisks)
  : [];

const riskRegisterUnavailable =
  isProjectWide && risks.length === 0;

const riskExtractionStatus =
  !isProjectWide
    ? 'not_applicable_focused_or_sprint_scope'
    : risks.length > 0
      ? 'extracted'
      : contextHasRiskFilename
        ? 'source_detected_records_not_parsed'
        : 'risk_source_not_in_reporter_context';

// ==================================================
// 11. SOURCE REFERENCES
// ==================================================

const sourceRefs = unique([
  'sample_task_board.csv',

  ...(risks.length
    ? ['project_risks.csv']
    : []),

  ...arr(parsed.source_references)
    .filter(x => typeof x === 'string')
    .map(str)
    .filter(Boolean)
    .filter(ref =>
      !isFocused ||
      !/project_risks\.csv/i.test(ref)
    )
]);

// ==================================================
// 12. MODEL DISCREPANCIES
// ==================================================

const gaps = [];

const modelTotal =
  Number.isInteger(parsed.total_tasks)
    ? parsed.total_tasks
    : null;

const modelCountDiscrepancy =
  modelTotal !== null &&
  modelTotal !== tasks.length;

for (const gap of scopedStrings(parsed.data_gaps)) {
  gaps.push(gap);
}

if (isDeadlineFocused) {
  gaps.push(
    'Current live task status and snapshot effective date were not verified; ' +
    'recorded due dates are compared to report generation date for review only.'
  );
}

// ==================================================
// 13. BUILD STAKEHOLDER DRAFT
// ==================================================

const incomingEmail = obj(parsed.email_draft);

const suppliedDraft =
  typeof parsed.draft_stakeholder_update === 'string'
    ? parsed.draft_stakeholder_update
    : str(incomingEmail.body);

const draftHasValidScope =
  referencesOnlySelectedTasks(suppliedDraft);

// Check whether a draft references named risks.

const normalizedDraft = suppliedDraft.toLowerCase();

const riskNames = canonicalRisks
  .map(r => {
    const match = r.match(
      /(?:^|;)\s*category:\s*([^;]+)/i
    );

    return match
      ? match[1].trim().toLowerCase()
      : '';
  })
  .filter(Boolean);

const draftMentionsNamedRisks =
  /\bR\d{1,3}\b/i.test(suppliedDraft) ||
  riskNames.some(name =>
    normalizedDraft.includes(name)
  );

const sprintRiskMismatch =
  !isProjectWide &&
  risks.length === 0 &&
  draftMentionsNamedRisks;

const progressLines = selected
  .filter(t =>
    t.status === 'Done' ||
    t.status === 'In Progress'
  )
  .map(t =>
    `- ${t.task_id}: ${t.task_name} — ` +
    `${t.status}` +
    (t.assignee
      ? ` (${t.assignee})`
      : '')
  );

const remainingLines = selected
  .filter(t => t.status === 'To Do')
  .map(t =>
    `- ${t.task_id}: ${t.task_name} — To Do`
  );

const riskStatement =
  risks.length
    ? risks.map(r => `- ${r}`).join('\n')
    : isProjectWide
      ? 'Risk-register content could not be retrieved by this reporting process. Risk coverage is incomplete and requires source verification.'
      : isFocused
        ? 'Project risk register not requested for this focused task analysis.'
        : 'No sprint-specific risk statements have been independently established for this report.';

const fallbackDraft = [
  'DRAFT — Stakeholder Status Update',
  '',
  `Scope: ${
    isBlockedOnly
      ? (
          sprint
            ? `${sprint} blocked tasks`
            : 'Blocked tasks only'
        )
      : isDeadlineFocused
        ? (
            sprint
              ? `${sprint} deadline review`
              : 'Blockers and deadline review'
          )
        : (sprint || 'Full project task board')
  }`,
  '',
  canonicalSummary,
  '',
  'Recorded progress:',
  progressLines.length
    ? progressLines.join('\n')
    : 'No Done or In Progress tasks recorded.',
  '',
  'Remaining work:',
  remainingLines.length
    ? remainingLines.join('\n')
    : 'No To Do tasks recorded.',
  '',
  'Documented blockers:',
  blockers.length
    ? blockers.map(b => `- ${b}`).join('\n')
    : 'None recorded within this reporting scope.',
  '',
  'Relevant risks:',
  riskStatement,
  '',
  'This draft reflects the supplied project snapshot.',
  'Current live task status has not been independently verified.',
  '',
  'Human review is required before distribution.'
].join('\n');

// Preserve valid sprint-specific model drafts.
// Use source-derived drafts for full-project
// and blocked-task-only reports.

const focusedDeadlineDraft = [
  'DRAFT — Stakeholder Status Update',
  '',
  `Scope: ${scopeLabel}`,
  '',
  canonicalSummary,
  '',
  'Documented blockers:',
  blockers.length
    ? blockers.map(b => `- ${b}`).join('\n')
    : 'None recorded.',
  '',
  `${additionalDeadlineConcerns.length} additional unfinished tasks have historical due-date concerns.`,
  'Recorded statuses have not been verified as current.',
  'Human review is required before distribution.'
].join('\n');

const emailBody = isDeadlineFocused
  ? focusedDeadlineDraft
  : !isBlockedOnly &&
    suppliedDraft &&
    draftHasValidScope &&
    !modelScopeMismatch &&
    !isProjectWide &&
    !sprintRiskMismatch
      ? suppliedDraft
      : fallbackDraft;

const draftBody =
  /^\s*DRAFT\b/i.test(emailBody)
    ? emailBody
    : `DRAFT — NOT SENT\n\n${emailBody}`;

const email_draft = {
  subject:
    (
      !modelScopeMismatch
        ? str(incomingEmail.subject)
        : ''
    ) ||
    `Draft: ${
      isBlockedOnly
        ? 'Blocked tasks'
        : isDeadlineFocused
          ? 'Blockers and deadline concerns'
          : (sprint || 'Project-wide')
    } status update`,

  body: draftBody,
  is_draft: true
};

// ==================================================
// 14. STATUS VALIDATION
// ==================================================

const validated =
  countsMatch &&
  blockersMatch &&
  !hasDuplicateIds &&
  invalidTasks.length === 0;

if (!validated) {
  return failure(
    'Canonical task or blocker reconciliation failed.'
  );
}

// ==================================================
// 15. OUTPUT WITH LEGACY COMPATIBILITY
// ==================================================

return [{
  json: {
    ...base,

    status: 'ok',

    project_name:
      str(parsed.project_name) ||
      str(trig.project_name) ||
      str(obj(structuredContext).project_name) ||
      str(obj(structuredContext).project),

    sprint: sprint || null,

    as_of_date: parsed.as_of_date ?? null,

    summary,
    total_tasks: tasks.length,
    status_counts,
    tasks,
    highlights,
    blockers,
    risks,
    source_references: sourceRefs,
    draft_stakeholder_update: draftBody,

    // Legacy output compatibility

    report_period:
      sprint ||
      (isBlockedOnly
        ? 'Blocked tasks'
        : isDeadlineFocused
          ? 'Blockers and deadline concerns'
          : 'All project sprints'),

    overall_rag: 'Unknown',
    executive_summary: summary,
    workstreams: [],
    task_counts,
    upcoming: [],
    issues_and_blockers: blockers,
    email_draft,
    data_gaps: gaps,

    // Reconciliation diagnostics

    task_counts_validated: countsMatch,
    task_counts_reconciled: countsMatch,
    blocker_reconciliation_pass: blockersMatch,

    // Model diagnostics

    model_count_discrepancy:
      modelCountDiscrepancy,

    model_scope_mismatch:
      modelScopeMismatch,

    sprint_risk_draft_mismatch:
      sprintRiskMismatch,

    model_reported_sprint:
      modelSprint || null,

    // Source-access diagnostics

    risk_register_unavailable:
      riskRegisterUnavailable,

    risk_extraction_status:
      riskExtractionStatus,

    risk_records_extracted:
      canonicalRisks.length,

    context_has_risk_filename:
      contextHasRiskFilename,

    context_has_risk_ids:
      contextHasRiskIds,

    context_risk_files:
      contextRiskFiles,

    context_characters:
      contextText.length,

    validation_status: 'PARTIAL'
  }
}];

